import { Component } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import {
  TablerIconComponent,
  IconId, IconIdFilled,
  IconFileText, IconFileTextFilled,
  IconStar, IconStarFilled,
} from '@tabler/icons-angular';
import { HrmTabs, HrmTab } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Tabs (Navigation) — cấu trúc chuẩn: Icon đổi khi chọn / Cơ bản / Kích thước / Kiểu. Song ngữ qua i18n docs.tabs.*. */
@Component({
  selector: 'sg-doc-tabs',
  imports: [TranslateModule, TablerIconComponent, HrmTabs, HrmTab, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Navigation" [title]="'docs.tabs.title' | translate" [desc]="'docs.tabs.desc' | translate">

      <div sgOverview>
        <div style="width:100%;max-width:520px">
          <hrm-tabs>
            <hrm-tab [title]="'docs.tabs.tabOverview' | translate"><div class="tb">{{ 'docs.tabs.bodyOverview' | translate }}</div></hrm-tab>
            <hrm-tab [title]="'docs.tabs.tabDetail' | translate"><div class="tb">{{ 'docs.tabs.bodyDetail' | translate }}</div></hrm-tab>
            <hrm-tab [title]="'docs.tabs.tabHistory' | translate"><div class="tb">{{ 'docs.tabs.bodyHistory' | translate }}</div></hrm-tab>
          </hrm-tabs>
        </div>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.tabs.purpose' | translate"
          [when]="when"
          [behavior]="'docs.tabs.behavior' | translate"
          [avoid]="'docs.tabs.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.tabs.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.tabs.do2' | translate }}</sg-do>
        <sg-do>{{ 'docs.tabs.do3' | translate }}</sg-do>
        <sg-dont>{{ 'docs.tabs.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.tabs.exIconT' | translate"
          [desc]="'docs.tabs.exIconD' | translate">
          <sg-row>
            <div style="width:100%;max-width:520px">
              <div class="tabbar" role="tablist">
                <button type="button" class="tabbtn" [class.on]="idx === 0" (click)="idx = 0">
                  <tabler-icon [icon]="$any(idx === 0 ? idFilled : idOutline)" [size]="18" />
                  <span>{{ 'docs.tabs.tabInfo' | translate }}</span>
                </button>
                <button type="button" class="tabbtn" [class.on]="idx === 1" (click)="idx = 1">
                  <tabler-icon [icon]="$any(idx === 1 ? fileFilled : fileOutline)" [size]="18" />
                  <span>{{ 'docs.tabs.tabContract' | translate }}</span>
                </button>
                <button type="button" class="tabbtn" [class.on]="idx === 2" (click)="idx = 2">
                  <tabler-icon [icon]="$any(idx === 2 ? starFilled : starOutline)" [size]="18" />
                  <span>{{ 'docs.tabs.tabReview' | translate }}</span>
                </button>
              </div>
              <hrm-tabs [(selectedIndex)]="idx" style="display:none">
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate" /><hrm-tab [title]="'docs.tabs.tabContract' | translate" /><hrm-tab [title]="'docs.tabs.tabReview' | translate" />
              </hrm-tabs>
              <div class="tb">
                @switch (idx) {
                  @case (0) { {{ 'docs.tabs.bodyInfoIcon' | translate }} }
                  @case (1) { {{ 'docs.tabs.bodyContractIcon' | translate }} }
                  @case (2) { {{ 'docs.tabs.bodyReviewIcon' | translate }} }
                }
              </div>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.tabs.exBasicT' | translate"
          [desc]="'docs.tabs.exBasicD' | translate">
          <sg-row>
            <div style="width:100%;max-width:520px">
              <hrm-tabs>
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate"><div class="tb">{{ 'docs.tabs.bodyInfoBasic' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabContract' | translate"><div class="tb">{{ 'docs.tabs.bodyContractBasic' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabHistory' | translate"><div class="tb">{{ 'docs.tabs.bodyHistoryLog' | translate }}</div></hrm-tab>
              </hrm-tabs>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.tabs.exSizeT' | translate"
          [desc]="'docs.tabs.exSizeD' | translate">
          <sg-row label="small · default · large">
            <div style="width:100%;max-width:520px">
              <hrm-tabs size="small">
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate"><div class="tb">{{ 'docs.tabs.bodySizeSm' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabContract' | translate"><div class="tb">{{ 'docs.tabs.bodySizeSm' | translate }}</div></hrm-tab>
              </hrm-tabs>
            </div>
            <div style="width:100%;max-width:520px">
              <hrm-tabs size="default">
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate"><div class="tb">{{ 'docs.tabs.bodySizeMd' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabContract' | translate"><div class="tb">{{ 'docs.tabs.bodySizeMd' | translate }}</div></hrm-tab>
              </hrm-tabs>
            </div>
            <div style="width:100%;max-width:520px">
              <hrm-tabs size="large">
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate"><div class="tb">{{ 'docs.tabs.bodySizeLg' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabContract' | translate"><div class="tb">{{ 'docs.tabs.bodySizeLg' | translate }}</div></hrm-tab>
              </hrm-tabs>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.tabs.exTypeT' | translate"
          [desc]="'docs.tabs.exTypeD' | translate">
          <sg-row label="line · card">
            <div style="width:100%;max-width:520px">
              <hrm-tabs type="line">
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate"><div class="tb">{{ 'docs.tabs.bodyTypeLine' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabContract' | translate"><div class="tb">{{ 'docs.tabs.bodyTypeLine' | translate }}</div></hrm-tab>
              </hrm-tabs>
            </div>
            <div style="width:100%;max-width:520px">
              <hrm-tabs type="card">
                <hrm-tab [title]="'docs.tabs.tabInfo' | translate"><div class="tb">{{ 'docs.tabs.bodyTypeCard' | translate }}</div></hrm-tab>
                <hrm-tab [title]="'docs.tabs.tabContract' | translate"><div class="tb">{{ 'docs.tabs.bodyTypeCard' | translate }}</div></hrm-tab>
              </hrm-tabs>
            </div>
          </sg-row>
        </sg-example>
      </div>

    </sg-doc>
  `,
  styles: [`
    .tb { padding:12px 4px; color:var(--text-body); font-size: var(--fs-14); }
    .tabbar { display:flex; gap:4px; border-bottom:1px solid var(--border-sub); }
    .tabbtn {
      display:inline-flex; align-items:center; gap:8px; cursor:pointer;
      border:0; background:transparent; padding:8px 14px; margin-bottom:-1px;
      border-bottom:2px solid transparent; border-radius:var(--radius-md) var(--radius-md) 0 0;
      font-family:var(--font-sans); font-size: var(--fs-14); font-weight:500; color:var(--text-sub);
    }
    .tabbtn:hover { color:var(--text-strong); background:var(--bg-surface-subtle); }
    .tabbtn.on { color:var(--primary-base); border-bottom-color:var(--primary-base); }
  `],
})
export class SgDocTabs {
  protected readonly idOutline = IconId;
  protected readonly idFilled = IconIdFilled;
  protected readonly fileOutline = IconFileText;
  protected readonly fileFilled = IconFileTextFilled;
  protected readonly starOutline = IconStar;
  protected readonly starFilled = IconStarFilled;
  protected idx = 0;
  protected readonly when = [
    'docs.tabs.when1',
    'docs.tabs.when2',
    'docs.tabs.when3',
  ];
}
